 add(f'- {names[p]}: AUC {r["auc"]:.4f}, AP {r["average_precision"]:.4f}. Liver-target precision exceeds 50% at the tested overall attraction rates {", ".join(qual)}. At 10% attraction: precision {pct(point["liver_target_precision"])}, liver-pair recall {pct(point["liver_pair_recall"])}. Producer: `score.py --pool {p}`.')
